// Step 2: Extract student code from either direct JSON payload or uploaded file
const item = $input.first();
let code = "";
let language = "python";
let studentName = "Student";
let studentEmail = "student@university.edu";
let problemTitle = "Practice Challenge";
let hintsUsed = 0;

// Check if file upload was provided
if (item.binary && item.binary.file) {
  const fileData = item.binary.file;
  const raw = Buffer.from(fileData.data, 'base64').toString('utf-8');
  code = raw;
  const fileName = (fileData.fileName || "").toLowerCase();
  if (fileName.endsWith(".java")) {
    language = "java";
  } else {
    language = "python";
  }
  studentName = fileData.fileName || "Uploaded Code";
} else {
  // Standard JSON payload from CodeSense platform
  const body = item.json.body || item.json;
  code = body.code || "";
  language = body.language || "python";
  studentName = body.student_name || "Akshayaa";
  studentEmail = body.student_email || "student@codesense.edu";
  problemTitle = body.problem_title || "Array & Logic Challenge";
  hintsUsed = Number(body.hints_used || 0);
}

return [{
  json: {
    student_name: studentName,
    student_email: studentEmail,
    problem_title: problemTitle,
    language: language,
    code: code,
    hints_used: hintsUsed,
    timestamp: new Date().toISOString()
  }
}];

