parameters.jsCode:
// Step 4: Parse AI response and merge with submission metadata
const rawAi = $input.first().json;
const meta = $('2. Parse Student Submission & File').first().json;

let parsed = {};
try {
  if (rawAi.choices && rawAi.choices[0] && rawAi.choices[0].message) {
    parsed = JSON.parse(rawAi.choices[0].message.content);
  } else {
    parsed = rawAi;
  }
} catch (e) {
  parsed = {
    score: meta.hints_used > 2 ? 65 : 85,
    status: meta.hints_used > 2 ? 'Needs Remediation' : 'Mastered',
    misconception_detected: 'Potential edge condition handling',
    core_concept: 'Algorithmic iteration and bounds',
    recommended_action: 'Trace loop boundaries with edge values [0] and [N-1]',
    next_recommended_topic: 'Two Pointer Technique',
    autonomy_badge: 'Independent Thinker'
  };
}

return [{
  json: {
    ...meta,
    evaluation: parsed,
    score: parsed.score || 75,
    status: parsed.status || 'Needs Remediation',
    is_mastered: (parsed.score || 75) >= 75
  }
}];

// Branch True: High Mastery Action (Student Autonomous Advancement)
const data = $input.first().json;
return [{
  json: {
    ...data,
    automation_action: "ADVANCE_STUDENT",
    congratulations_message: `🌟 Outstanding mastery on ${data.problem_title}! You have earned the '${data.evaluation.autonomy_badge}' badge.`,
    next_milestone: `Unlocking next progressive tier: ${data.evaluation.next_recommended_topic}`
  }
}];

// Branch False: Remedial Intervention Action (Automated Targeted Help)
const data = $input.first().json;
return [{
  json: {
    ...data,
    automation_action: "REMEDIAL_INTERVENTION",
    alert_message: `⚠️ Logic gap detected: ${data.evaluation.misconception_detected}`,
    guided_remedy: `Focus on: ${data.evaluation.core_concept}. Recommended next step: ${data.evaluation.recommended_action}`
  }
}];
